fn chars_list(s: Str) -> List[Str] {
    var out: List[Str] = []
    for c in s.chars() {
        out = out.push(c)
    }
    return out
}

fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn is_digit(c: Str) -> Bool {
    return c >= "0" and c <= "9"
}

fn is_letter(c: Str) -> Bool {
    return (c >= "a" and c <= "z") or (c >= "A" and c <= "Z") or c == "_"
}

fn is_single(c: Str) -> Bool {
    return c == "+" or c == "-" or c == "*" or c == "/" or c == "<" or c == ">" or c == "=" or c == "(" or c == ")" or c == "{" or c == "}" or c == "," or c == ";"
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
    let cs = chars_list(s: src)
    let n = cs.len()
    var out: List[Str] = []
    var i = 0
    while i < n {
        let c = str_at(cs, i)
        let nxt = str_at(cs, i + 1)
        if c == " " or c == "\t" or c == "\n" {
            i = i + 1
        } else if is_letter(c) {
            var tok = ""
            var j = i
            while j < n and (is_letter(str_at(cs, j)) or is_digit(str_at(cs, j))) {
                tok = tok + str_at(cs, j)
                j = j + 1
            }
            out = out.push(tok)
            i = j
        } else if is_digit(c) {
            var tok = ""
            var j = i
            while j < n and is_digit(str_at(cs, j)) {
                tok = tok + str_at(cs, j)
                j = j + 1
            }
            out = out.push(tok)
            i = j
        } else if c == "\"" {
            var tok = "\""
            var j = i + 1
            var closed = false
            while j < n and not closed {
                let d = str_at(cs, j)
                if d == "\\" {
                    tok = tok + d
                    if j + 1 < n {
                        tok = tok + str_at(cs, j + 1)
                    }
                    j = j + 2
                } else if d == "\"" {
                    tok = tok + d
                    closed = true
                    j = j + 1
                } else {
                    tok = tok + d
                    j = j + 1
                }
            }
            if not closed {
                return Err("unterminated string")
            }
            out = out.push(tok)
            i = j
        } else if nxt != "" and (c + nxt == "==" or c + nxt == "!=" or c + nxt == "<=" or c + nxt == ">=" or c + nxt == "->") {
            out = out.push(c + nxt)
            i = i + 2
        } else if is_single(c) {
            out = out.push(c)
            i = i + 1
        } else {
            return Err("unexpected " + c)
        }
    }
    return Ok(out)
}
